import inspect


def output_types(**sockets):
    def decorate(fn):
        fn.__output_types__ = dict(sockets)
        return fn
    return decorate


class Pipeline:
    def __init__(self):
        self.components = {}
        self.connections = []

    def add_component(self, name, instance):
        if name in self.components:
            raise ValueError(f"component {name!r} already added")
        self.components[name] = instance
        return self

    def input_sockets(self, name):
        run = self.components[name].run
        sockets = {}
        for parameter in inspect.signature(run).parameters.values():
            sockets[parameter.name] = (
                parameter.annotation
                if parameter.annotation is not inspect.Parameter.empty else object,
                parameter.default is not inspect.Parameter.empty,
            )
        return sockets

    def output_sockets(self, name):
        return dict(getattr(self.components[name].run, "__output_types__", {}))

    def _resolve(self, spec, sockets, side):
        if "." in spec:
            name, _, socket = spec.partition(".")
        else:
            name, socket = spec, None
        if name not in self.components:
            raise ValueError(f"no component {name!r}")
        available = sockets(name)
        if socket is None:
            if len(available) != 1:
                raise ValueError(
                    f"{name!r} has {len(available)} {side} sockets; name one")
            socket = next(iter(available))
        if socket not in available:
            raise ValueError(f"{name!r} has no {side} socket {socket!r}")
        return name, socket

    def connect(self, sender, receiver):
        from_name, from_socket = self._resolve(sender, self.output_sockets, "output")
        to_name, to_socket = self._resolve(receiver, self.input_sockets, "input")
        produced = self.output_sockets(from_name)[from_socket]
        wanted = self.input_sockets(to_name)[to_socket][0]
        if wanted is not object and produced is not wanted:
            compatible = (isinstance(produced, type) and isinstance(wanted, type)
                          and issubclass(produced, wanted))
            if not compatible:
                raise ValueError(
                    f"cannot connect {from_name}.{from_socket} ({produced}) to "
                    f"{to_name}.{to_socket} ({wanted})")
        self.connections.append((from_name, from_socket, to_name, to_socket))
        return self

    def run(self, inputs=None):
        inputs = {name: dict(values) for name, values in (inputs or {}).items()}
        for name in inputs:
            if name not in self.components:
                raise ValueError(f"no component {name!r}")

        incoming = {name: [] for name in self.components}
        for connection in self.connections:
            incoming[connection[2]].append(connection)

        pending = set(self.components)
        results = {}
        while pending:
            ready = [name for name in pending
                     if all(c[0] not in pending for c in incoming[name])]
            if not ready:
                raise ValueError("pipeline has a cycle")
            for name in sorted(ready):
                args = dict(inputs.get(name, {}))
                for from_name, from_socket, _, to_socket in incoming[name]:
                    if to_socket in args:
                        raise ValueError(
                            f"{name}.{to_socket} is wired and was also given a value")
                    args[to_socket] = results[from_name][from_socket]
                for socket, (_, optional) in self.input_sockets(name).items():
                    if socket not in args and not optional:
                        raise ValueError(f"{name}.{socket} has no value")
                results[name] = self.components[name].run(**args)
                pending.discard(name)

        consumed = {connection[0] for connection in self.connections}
        return {name: value for name, value in results.items() if name not in consumed}

