class Document:
    def __init__(self, content, score=0.0):
        self.content = content
        self.score = score

    def __repr__(self):
        return f"Document({self.content!r})"


class Retriever:
    def __init__(self, store):
        self.store = store

    @output_types(documents=list)
    def run(self, query: str, top_k: int = 2):
        wanted = set(query.lower().split())
        ranked = sorted(self.store,
                        key=lambda d: -len(wanted & set(d.content.lower().split())))
        return {"documents": ranked[:top_k]}


class PromptBuilder:
    @output_types(prompt=str)
    def run(self, documents: list, question: str):
        body = "\n".join(f"- {d.content}" for d in documents)
        return {"prompt": f"Context:\n{body}\nQuestion: {question}"}


class Generator:
    def __init__(self, tag):
        self.tag = tag

    @output_types(replies=list)
    def run(self, prompt: str):
        return {"replies": [f"[{self.tag}] {prompt.splitlines()[1]}"]}


STORE = [Document("Haystack builds pipelines of typed components"),
         Document("Paris is the capital of France"),
         Document("BM25 ranks documents by keyword matching")]

pipe = Pipeline()
pipe.add_component("retriever", Retriever(STORE))
pipe.add_component("prompt", PromptBuilder())
pipe.add_component("llm", Generator("gpt"))
pipe.connect("retriever.documents", "prompt.documents")
pipe.connect("prompt.prompt", "llm.prompt")

# Sockets are read off the code: parameter hints are inputs, the decorator declares
# outputs, and a parameter with a default is an optional socket.
assert pipe.output_sockets("retriever") == {"documents": list}
assert pipe.input_sockets("prompt") == {"documents": (list, False),
                                        "question": (str, False)}, pipe.input_sockets("prompt")
assert pipe.input_sockets("retriever")["top_k"] == (int, True)

# Inputs are addressed by COMPONENT name, and only leaf outputs come back -- the
# intermediate documents and prompt travelled along the wires.
out = pipe.run({"retriever": {"query": "what is Haystack"},
                "prompt": {"question": "what is Haystack"}})
assert list(out) == ["llm"], out
assert out["llm"]["replies"] == ["[gpt] - Haystack builds pipelines of typed components"], out

# The payoff of the graph: swap one chip, rewire identically, everything else is
# untouched.
swapped = Pipeline()
swapped.add_component("retriever", Retriever(STORE))
swapped.add_component("prompt", PromptBuilder())
swapped.add_component("llm", Generator("local"))
swapped.connect("retriever.documents", "prompt.documents")
swapped.connect("prompt.prompt", "llm.prompt")
assert swapped.run({"retriever": {"query": "capital of France"},
                    "prompt": {"question": "where"}})["llm"]["replies"] == \
    ["[local] - Paris is the capital of France"]

# A wire whose ends do not fit is refused when it is drawn, not deep in a run.
bad = Pipeline()
bad.add_component("retriever", Retriever(STORE))
bad.add_component("llm", Generator("x"))
try:
    bad.connect("retriever.documents", "llm.prompt")
except ValueError:
    pass
else:
    raise AssertionError("a list output must not connect to a string input")

for wrong in [("retriever.docs", "llm.prompt"), ("retriever.documents", "llm.input"),
              ("nobody.documents", "llm.prompt")]:
    try:
        bad.connect(*wrong)
    except ValueError:
        continue
    raise AssertionError(f"{wrong} must be refused")

# Naming the socket is optional only when there is exactly one candidate.
short = Pipeline()
short.add_component("retriever", Retriever(STORE))
short.add_component("prompt", PromptBuilder())
short.connect("retriever", "prompt.documents")
assert short.connections == [("retriever", "documents", "prompt", "documents")]
try:
    short.connect("retriever.documents", "prompt")
except ValueError:
    pass
else:
    raise AssertionError("an ambiguous receiving end must be named")

# A socket that is already fed by a wire cannot also be handed a value.
try:
    pipe.run({"retriever": {"query": "q"}, "prompt": {"question": "q",
                                                      "documents": []}})
except ValueError:
    pass
else:
    raise AssertionError("a wired socket must not also be supplied")

# A required socket with nothing feeding it is an error naming the socket.
try:
    pipe.run({"retriever": {"query": "q"}})
except ValueError as exc:
    assert "prompt.question" in str(exc), exc
else:
    raise AssertionError("a missing required input must be refused")

# Components run in dependency order however they were added.
order = []


class Recorder:
    def __init__(self, label):
        self.label = label

    @output_types(value=str)
    def run(self, value: str = "seed"):
        order.append(self.label)
        return {"value": value + self.label}


late = Pipeline()
late.add_component("third", Recorder("c"))
late.add_component("first", Recorder("a"))
late.add_component("second", Recorder("b"))
late.connect("first.value", "second.value")
late.connect("second.value", "third.value")
assert late.run()["third"] == {"value": "seedabc"}, late.run()
assert order[:3] == ["a", "b", "c"], order

# A cycle is reported rather than hung on.
loop = Pipeline()
loop.add_component("x", Recorder("x"))
loop.add_component("y", Recorder("y"))
loop.connect("x.value", "y.value")
loop.connect("y.value", "x.value")
try:
    loop.run()
except ValueError:
    pass
else:
    raise AssertionError("a cycle must be reported")
